Lemma zeros_bytes_at : forall m x k, 0 <= x -> x + Z.of_nat k <= 2^64 ->
  (forall o, 0 <= o < Z.of_nat k -> bytes_at asegs m (x + o) [b8 0]) -> bytes_at asegs m x (zeros k).
Proof.
